const fs = require('fs');
const path = require('path');
const assert = require('assert').strict;
const engine = require('../../.typology-matrix-build/src/components/amphitheaterPrototype.js');
const fixture = JSON.parse(fs.readFileSync(path.join(__dirname, '../full-domain-validation/fixture.json'), 'utf8'));

const requestedMode = process.argv.find((argument) => ['letters', 'voids', 'combined'].includes(argument));
const modes = requestedMode ? [requestedMode] : ['letters', 'voids', 'combined'];
const geometric = (element) => ({ kind: element.kind, z: element.z, height: element.height, footprint: element.footprint, innerFootprint: element.innerFootprint, rise: element.rise });
const center = (element) => element.footprint?.length ? [element.footprint.reduce((sum,p)=>sum+p[0],0)/element.footprint.length,element.footprint.reduce((sum,p)=>sum+p[1],0)/element.footprint.length] : [element.x,element.y];
const geometryText = (variation) => JSON.stringify(variation.disconnectedElements.map(geometric));
const perturb = fixture.source.map((item, index) => index % 17 === 0
  ? { ...item, x: item.x + .31, y: item.y - .18, z: item.z + .23, rz: item.rz + 19 }
  : item);

const preview = Object.fromEntries(modes.map((mode) => [mode, engine.generateProtoArchitecture({ ...fixture, typology: 'flat-deep-plan-plate', category: 'office', mode, quality: 'preview' })]));
const changed = Object.fromEntries(modes.map((mode) => [mode, engine.generateProtoArchitecture({ ...fixture, source: perturb, typology: 'flat-deep-plan-plate', category: 'office', mode, quality: 'preview' })]));
for (const mode of modes) {
  assert(preview[mode].fullFormDiagnostic?.fullVolumetricSourceUsed, `${mode}: full volume flag`);
  assert(preview[mode].unifiedSourceElements?.length, `${mode}: unified source elements`);
  assert.notEqual(geometryText(preview[mode]), geometryText(changed[mode]), `${mode}: perturbation must change primary pre-SDF geometry`);
}

if (process.argv.includes('--preview-only')) {
  console.log(JSON.stringify(modes.map((mode) => ({ mode, diagnostic: preview[mode].fullFormDiagnostic, unifiedSourceElements: preview[mode].unifiedSourceElements.length, primaryElements: preview[mode].disconnectedElements.length, connectors: preview[mode].connectorElements.length,
    plates: preview[mode].disconnectedElements.filter(element=>element.kind==='platform'||element.kind==='stage').map(element=>({id:element.id,center:center(element),z:element.z,height:element.height})),
    routes: preview[mode].connectorElements.filter(element=>element.id.includes('domain-route')).map(element=>({id:element.id,from:element.slopeFrom,to:element.slopeTo,z:element.z,height:element.height,widthArea:element.footprint&&Math.abs(element.footprint.reduce((sum,p,i)=>sum+p[0]*element.footprint[(i+1)%element.footprint.length][1]-element.footprint[(i+1)%element.footprint.length][0]*p[1],0)/2)})) })), null, 2));
  process.exit(0);
}

const results = [];
(async () => {
  for (const mode of modes) {
    const variation = engine.generateProtoArchitecture({ ...fixture, typology: 'flat-deep-plan-plate', category: 'office', mode, quality: 'final' });
    const d = variation.fullFormDiagnostic;
    results.push({
      mode,
      sourceComponentsBeforeUnion: d.sourceComponentsBeforeUnion,
      sourceComponentsAfterUnion: d.sourceComponentsAfterUnion,
      disconnectedSourceGroups: d.disconnectedSourceGroups,
      sourceExtent: d.sourceExtent,
      architectureExtent: d.architectureExtent,
      volumetricRepresentation: d.volumetricRepresentation,
      relationshipGraphEdges: d.relationshipGraphEdges,
      architecturalConnectors: d.architecturalConnectors,
      finalMeshComponents: d.finalMeshComponents,
      componentBounds: variation.continuousMesh.componentBounds,
      continuousCirculation: d.continuousCirculation,
      fullVolumetricSourceUsed: d.fullVolumetricSourceUsed,
      graphUsedAsSecondaryOrganizer: d.graphUsedAsSecondaryOrganizer,
      unifiedSourceElements: variation.unifiedSourceElements.length,
      primaryElementsBeforeConnections: variation.disconnectedElements.length,
      perturbationChangedPrimaryGeometry: geometryText(preview[mode]) !== geometryText(changed[mode]),
      failures: variation.validation.failures,
      architecturalFailures: variation.architecturalValidation.failures,
    });
  }
  fs.writeFileSync(path.join(__dirname, 'results.json'), JSON.stringify({ fixture: 'full-domain-validation/fixture.json', typology: 'O3 — Flat Deep-Plan Plate', results }, null, 2));
  console.log(JSON.stringify(results, null, 2));
})().catch((error) => { console.error(error); process.exitCode = 1; });

const fs=require('fs'),path=require('path'),assert=require('assert/strict');
const root=path.resolve(__dirname,'../..'),e=require(path.join(root,'.typology-matrix-build/src/components/amphitheaterPrototype.js')),f=require('../full-domain-validation/fixture.json');
const analysis=e.analyzeSourceGeometry(f.source,true),rows=[];
const identity=p=>`${p.cell.id}@${p.sourceIndex??'member'}:${p.layerIndex??0}`;
const geometry=elements=>elements.map(({id,provenance,...g})=>JSON.stringify(g)).sort().join('|');
for(const typology of ['contained-room-within-volume','flat-deep-plan-plate','vertical-void-lobby'])for(const mode of ['letters','voids','combined']){
 const generate=(source,a)=>e.generateProtoArchitecture({...f,source,sourceAnalysis:a,typology,mode,quality:'preview'}),base=generate(f.source,analysis);
 const targets=r=>r.disconnectedElements.filter(x=>typology==='contained-room-within-volume'?x.id.endsWith('-contained-room'):typology==='flat-deep-plan-plate'?x.id.includes('-courtyard-'):x.id.includes('primary-space-arrival')||x.id.includes('void-overlook'));
 const target=targets(base)[0],members=target.provenance.sourceLetterIds;let ids=target.provenance.sourceVoidIds;
 if(typology==='vertical-void-lobby'){const all=[...new Set(base.connectorElements.flatMap(x=>x.provenance?.sourceVoidIds||[]))];const chain=analysis.voids.filter(v=>all.includes(v.id)).sort((a,b)=>a.z-b.z);ids=[chain[Math.floor(chain.length/2)].id];}
 const row={typology,mode,tests:{}};
 for(const remove of [false,true]){
  let source=f.source,a=structuredClone(analysis);
  if(typology==='contained-room-within-volume'&&mode!=='voids'){source=remove?source.filter(p=>!members.includes(identity(p))):source.map(p=>members.includes(identity(p))?{...p,x:p.x+.45,y:p.y+.2,z:p.z+.15,rz:p.rz+20}:p);a=e.analyzeSourceGeometry(source,true);}
  else{a.voids=a.voids.filter(v=>!remove||!ids.includes(v.id)).map(v=>ids.includes(v.id)?{...v,center:[v.center[0]+.65,v.center[1]+.2],points:v.points.map(p=>[p[0]+.65,p[1]+.2]),z:v.z+.2,zMin:v.zMin+.2,zMax:v.zMax+.2}:v);const byId=new Map([...a.letters,...a.voids].map(v=>[v.id,v]));a.relationships=a.relationships.filter(x=>byId.has(x.fromId)&&byId.has(x.toId)).map(x=>({...x,from:byId.get(x.fromId).center,to:byId.get(x.toId).center,fromZ:byId.get(x.fromId).z,toZ:byId.get(x.toId).z}));}
  const result=generate(source,a),changed=geometry(targets(base))!==geometry(targets(result));assert(changed,typology+' '+mode+' actual target geometry unchanged');
  row.tests[remove?'assignedRemoval':'assignedMove']={actualTargetGeometryChanged:changed,identityAndProvenanceExcluded:true,unsupported:result.elements.length===0,baselineElements:targets(base).length,afterElements:targets(result).length};
 }
 rows.push(row);
}
fs.writeFileSync(path.join(__dirname,'causal-checks.json'),JSON.stringify(rows,null,2));console.log('All 18 target-geometry checks passed with IDs and provenance excluded.');

const fs=require('fs'),path=require('path'),assert=require('assert/strict'),Module=require('module'),ts=require('typescript');
const root=path.resolve(__dirname,'../..'),engine=require(path.join(root,'.typology-matrix-build/src/components/amphitheaterPrototype.js')),fixture=require('../full-domain-validation/fixture.json');
const analysis=engine.analyzeSourceGeometry(fixture.source,true),regions=new Map([...analysis.letters,...analysis.voids].map(r=>[r.id,r])),edges=new Set(analysis.relationships.map(e=>e.id)),members=new Set(fixture.source.map(p=>`${p.cell.id}@${p.sourceIndex??'member'}:${p.layerIndex??0}`));
for(const r of regions.values()){assert(r.memberIds?.length);r.memberIds.forEach(id=>assert(members.has(id),id));}
for(const e of analysis.relationships){assert(e.id);assert(regions.has(e.fromId)&&regions.has(e.toId));}
const rows=[];
for(const typology of ['contained-room-within-volume','flat-deep-plan-plate','vertical-void-lobby'])for(const mode of ['letters','voids','combined']){
 const args={...fixture,sourceAnalysis:analysis,typology,mode,quality:'preview'},r=engine.generateProtoArchitecture(args);
 for(const e of r.elements){assert(e.provenance);assert.equal(e.provenance.architecturalElementId,e.id);e.provenance.sourceRegionIds.forEach(id=>assert(regions.has(id)));e.provenance.sourceRelationshipIds.forEach(id=>assert(edges.has(id)));e.provenance.sourceLetterIds.forEach(id=>assert(members.has(id)));}
 const modified=structuredClone(fixture.descriptors);modified.openVolume.intensity=85;const changed=engine.generateProtoArchitecture({...args,descriptors:modified});const geometry=x=>JSON.stringify(x.elements.map(({provenance,...e})=>e));assert.notEqual(geometry(r),geometry(changed));
 rows.push({typology,mode,lineageValid:true,descriptorGeometryChanged:true,diagnostic:r.domainDiagnostic});
}
const noChain={...analysis,voids:analysis.voids.filter(v=>v.z===Math.min(...analysis.voids.map(r=>r.z)))};const ids=new Set([...noChain.letters,...noChain.voids].map(r=>r.id));noChain.relationships=noChain.relationships.filter(e=>ids.has(e.fromId)&&ids.has(e.toId));
for(const mode of ['letters','voids','combined']){const r=engine.generateProtoArchitecture({...fixture,typology:'vertical-void-lobby',mode,sourceAnalysis:noChain,quality:'preview'});assert.equal(r.elements.length,0);assert(r.validation.failures.some(s=>s.includes('UNSUPPORTED SOURCE FOR VERTICAL VOID LOBBY')));}
const file=path.join(root,'.typology-matrix-build/src/components/checkpoint.js'),baseline=new Module(file,module);baseline.filename=file;baseline.paths=Module._nodeModulePaths(path.dirname(file));baseline._compile(ts.transpileModule(fs.readFileSync(path.join(root,'checkpoints/2026-09-28-before-provenance/amphitheaterPrototype.ts.checkpoint.txt'),'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022,esModuleInterop:true}}).outputText,file);
const legacy=[];for(const typology of ['stepped-amphitheater','void-field-gathering','open-hall-workspace']){const args={...fixture,typology,mode:'combined',quality:'preview'},a=baseline.exports.generateProtoArchitecture(args),b=engine.generateProtoArchitecture(args);assert.deepEqual(b.presentationMesh.positions,a.presentationMesh.positions);assert.deepEqual(b.presentationMesh.indices,a.presentationMesh.indices);legacy.push({typology,previewMeshUnchanged:true});}
fs.writeFileSync(path.join(__dirname,'integrity.json'),JSON.stringify({rows,unsupportedChainAllModes:true,legacy},null,2));console.log('Lineage, descriptor, unsupported-chain and legacy preview checks passed.');

const fs=require('fs'),path=require('path'),sharp=require('sharp');
const rows=require('./results.json'),causal=require('./causal-checks.json');
const pct=(n,d)=>`${n}/${d} (${(100*n/Math.max(1,d)).toFixed(1)}%)`,xyz=a=>a?.map(x=>x.toFixed(2)).join(' × ')||'unsupported';
rows.sort((a,b)=>a.typology.localeCompare(b.typology)||['letters','voids','combined'].indexOf(a.mode)-['letters','voids','combined'].indexOf(b.mode));
let report='# Provenance correction measurements

All geometric comparisons exclude provenance and element IDs. The final matrix uses the deterministic 192-letter fixture, seed 2041, fixed descriptors, organic controls and extent.

## Local assignment coverage

| Typology | Mode | Original members | Regions | Relationships | Voids | Source-provenance elements | Fallback elements |
|---|---|---|---|---|---|---|---|
';
for(const r of rows){const d=r.diagnostic;report+=`| ${r.typology} | ${r.mode} | ${pct(d.lettersAssigned,d.lettersAvailable)} | ${pct(d.componentsUsed,d.componentsAvailable)} | ${pct(d.relationshipsUsed,d.relationshipsAvailable)} | ${pct(d.voidsAssigned,d.voidsAvailable)} | ${d.provenanceElements} | ${d.fallbackElements} |
`;}
report+='
Envelope-only influence is excluded from assigned-ID numerators. Void-support member IDs indicate nearby bounding letters, not necessarily occupied letter architecture. Source-provenance element totals include explicitly labeled envelope elements.

## Final reconstruction and targeted response

| Typology | Mode | Baseline components | Previous perturbation | Previous cluster removal | Assigned-feature move | Assigned-feature removal | Target geometry changes (move / removal) |
|---|---|---|---|---|---|---|---|
';
for(const r of rows){const c=causal.find(x=>x.typology===r.typology&&x.mode===r.mode);report+=`| ${r.typology} | ${r.mode} | ${['base','perturbation','removal','assignedMove','assignedRemoval'].map(k=>r.tests[k].components).join(' | ')} | ${c.tests.assignedMove.actualTargetGeometryChanged?'yes':'NO'} / ${c.tests.assignedRemoval.actualTargetGeometryChanged?'yes':'NO'} |
`;}
report+='
## Baseline extents (architectural feet, XYZ)

| Typology | Mode | Source | Raw | Final |
|---|---|---|---|---|
';for(const r of rows)report+=`| ${r.typology} | ${r.mode} | ${xyz(r.diagnostic.source)} | ${xyz(r.diagnostic.raw)} | ${xyz(r.diagnostic.final)} |
`;
report+='
## Exact feature assignments

';
let html=fs.readFileSync(path.join(__dirname,'SOURCE_INFLUENCE_MAP.html'),'utf8');
for(const r of rows){const name=r.typology+'-'+r.mode,record=JSON.parse(fs.readFileSync(path.join(__dirname,name+'-assignments.json'))),targets=record.elements.filter(e=>e.provenance?.role==='local'&&!e.id.includes('domain-landing')&&!e.id.includes('contained-enclosure'));
 report+=`### ${r.typology} / ${r.mode}

Target: ${r.target.architecturalElementId}

- Source regions: ${r.target.sourceRegionIds.join(', ')}
- Source voids: ${r.target.sourceVoidIds.join(', ')||'none'}
- Source members: ${r.target.sourceLetterIds.join(', ')}
- Source relationships: ${r.target.sourceRelationshipIds.join(', ')||'none internal to target'}

`;
 const ledger=`<details><summary>All major local assignments: source IDs → architectural element IDs</summary><table><tr><th>Architectural element</th><th>Source regions / voids</th><th>Source edges</th></tr>${targets.map(e=>`<tr><td>${e.id}</td><td>${e.provenance.sourceRegionIds.join('<br>')}</td><td>${e.provenance.sourceRelationshipIds.join('<br>')}</td></tr>`).join('')}</table></details>`;
 html=html.replace(`<a href="${name}-assignments.json">`,`${ledger}<a href="${name}-assignments.json">`);
}
fs.writeFileSync(path.join(__dirname,'MEASUREMENTS.md'),report);
html=html.replace('section{margin-bottom:50px}','section{margin-bottom:50px}td,th{border:1px solid #385057;padding:8px;vertical-align:top}table{border-collapse:collapse;width:100%;font-size:12px}details{margin:18px 0}');fs.writeFileSync(path.join(__dirname,'SOURCE_INFLUENCE_MAP.html'),html);
(async()=>{const types=['contained-room-within-volume','flat-deep-plan-plate','vertical-void-lobby'],modes=['letters','voids','combined'],parts=[];for(let r=0;r<3;r++)for(let c=0;c<3;c++)parts.push({input:await sharp(path.join(__dirname,types[r]+'-'+modes[c]+'-base.svg')).png().toBuffer(),left:c*500,top:r*440});await sharp({create:{width:1500,height:1320,channels:4,background:'#0b161b'}}).composite(parts).png().toFile(path.join(__dirname,'FINAL-COMPARISON.png'));})();

const fs=require('fs'),path=require('path'),crypto=require('crypto');
const root=path.resolve(__dirname,'../..'),engine=require(path.join(root,'.typology-matrix-build/src/components/amphitheaterPrototype.js')),fixture=require('../full-domain-validation/fixture.json');
const g4Letters=process.argv.includes('--g4-letters');
const types=(g4Letters?['contained-room-within-volume']:process.argv.includes('--l1')?['vertical-void-lobby']:['contained-room-within-volume','flat-deep-plan-plate','vertical-void-lobby']),modes=g4Letters?['letters']:['letters','voids','combined'],source=fixture.source,analysis=engine.analyzeSourceGeometry(source,true);
const oldChosen=require('../source-influence-validation/inputs.json').chosen;
const identity=p=>`${p.cell.id}@${p.sourceIndex??'member'}:${p.layerIndex??0}`;
const geometric=e=>{const {provenance,id,...geometry}=e;return geometry;};
const hash=x=>crypto.createHash('sha256').update(JSON.stringify(x)).digest('hex');
const center=e=>{const p=e?.footprint||[];return p.length?[p.reduce((s,p)=>s+p[0],0)/p.length,p.reduce((s,p)=>s+p[1],0)/p.length,e.z]:[];};
function changedAnalysis(ids,remove){const a=structuredClone(analysis);a.voids=a.voids.filter(v=>!remove||!ids.includes(v.id)).map(v=>ids.includes(v.id)?{...v,center:[v.center[0]+.65,v.center[1]+.2],points:v.points.map(p=>[p[0]+.65,p[1]+.2]),z:v.z+.2,zMin:v.zMin+.2,zMax:v.zMax+.2}:v);const map=new Map([...a.letters,...a.voids].map(v=>[v.id,v]));a.relationships=a.relationships.filter(e=>map.has(e.fromId)&&map.has(e.toId)).map(e=>({...e,from:map.get(e.fromId).center,to:map.get(e.toId).center,fromZ:map.get(e.fromId).z,toZ:map.get(e.toId).z}));return a;}
function svg(mesh,title){const p=mesh.positions,faces=[],project=i=>[250+(p[i*3]-p[i*3+2])*.707*13,260+((p[i*3]+p[i*3+2])*.37-p[i*3+1]*.86)*13];for(let i=0;i<mesh.indices.length;i+=3){const ids=mesh.indices.slice(i,i+3);faces.push({z:ids.reduce((s,j)=>s+p[j*3]+p[j*3+2]+p[j*3+1]*.4,0),s:`<polygon points="${ids.map(j=>project(j).join(',')).join(' ')}" fill="#b9cace" stroke="#84999d" stroke-width=".07"/>`});}faces.sort((a,b)=>a.z-b.z);return wrap(title,faces.map(f=>f.s).join(''));}
const wrap=(title,body)=>`<svg xmlns="http://www.w3.org/2000/svg" width="500" height="440"><rect width="500" height="440" fill="#0b161b"/><text x="12" y="24" fill="white" font-size="13">${title}</text>${body}</svg>`;
const project=(p,z)=>[250+(p[0]-p[1])*.707*13,260+((p[0]+p[1])*.37-z*.86)*13];
function mapSvg(base,target,title){const ids=new Set(target?.provenance?.sourceRegionIds||[]),color='#ffc76a';let body=[...analysis.letters,...analysis.voids].map(r=>`<polygon points="${r.points.map(p=>project(p,r.z).join(',')).join(' ')}" fill="none" stroke="${ids.has(r.id)?color:'#395459'}" stroke-width="${ids.has(r.id)?2:.4}"/>`).join('');body+=(target?.footprint?[`<polygon points="${target.footprint.map(p=>project(p,target.z).join(',')).join(' ')}" fill="${color}" fill-opacity=".25" stroke="${color}" stroke-width="2"/>`]:[]).join('');return wrap(title,body);}
const partial=process.argv.includes('--l1')||g4Letters;
const rows=partial?JSON.parse(fs.readFileSync(path.join(__dirname,'results.json'))).filter(r=>g4Letters?!(r.typology==='contained-room-within-volume'&&r.mode==='letters'):r.typology!=='vertical-void-lobby'):[];
const cards=partial?(fs.readFileSync(path.join(__dirname,'SOURCE_INFLUENCE_MAP.html'),'utf8').match(/<section>[\s\S]*?<\/section>/g)||[]).filter(s=>!s.includes(g4Letters?'<h2>contained-room-within-volume / letters':'<h2>vertical-void-lobby')):[];
for(const typology of types)for(const mode of modes){
 const generate=(src,a)=>engine.generateProtoArchitecture({...fixture,source:src,sourceAnalysis:a,typology,mode,quality:'final'});
 const base=generate(source,analysis),target=base.disconnectedElements.find(e=>typology==='contained-room-within-volume'?e.id.endsWith('-contained-room'):typology==='flat-deep-plan-plate'?e.id.includes('-courtyard-'):e.id.includes('primary-space-arrival'));
 if(!target)throw Error('Missing baseline target '+typology+' '+mode);
 let targetIds=target.provenance.sourceVoidIds,memberIds=target.provenance.sourceLetterIds;
 if(typology==='vertical-void-lobby'){const ids=[...new Set(base.connectorElements.flatMap(e=>e.provenance?.sourceVoidIds||[]))];const chain=analysis.voids.filter(v=>ids.includes(v.id)).sort((a,b)=>a.z-b.z);targetIds=[chain[Math.floor(chain.length/2)].id];}
 const rawLetterTarget=typology==='contained-room-within-volume'&&mode!=='voids';
 const cases={base};
 for(const test of ['perturbation','removal','assignedMove','assignedRemoval']){
   const t=Date.now();let src=source,a=analysis;
   if(test==='perturbation'){src=source.map(p=>oldChosen.includes(p.sourceIndex)?{...p,x:p.x+.35,y:p.y+.15,z:p.z+.2,rz:p.rz+30}:p);a=engine.analyzeSourceGeometry(src,true);}
   if(test==='removal'){src=source.filter(p=>!oldChosen.includes(p.sourceIndex));a=engine.analyzeSourceGeometry(src,true);}
   if(test.startsWith('assigned')){if(rawLetterTarget){src=test==='assignedRemoval'?source.filter(p=>!memberIds.includes(identity(p))):source.map(p=>memberIds.includes(identity(p))?{...p,x:p.x+.45,y:p.y+.2,z:p.z+.15,rz:p.rz+20}:p);a=engine.analyzeSourceGeometry(src,true);}else a=changedAnalysis(targetIds,test==='assignedRemoval');}
   cases[test]=generate(src,a);console.log(typology,mode,test,Date.now()-t,cases[test].presentationMesh.componentCount);
 }
 const identify=r=>r.disconnectedElements.filter(e=>typology==='contained-room-within-volume'?e.id.endsWith('-contained-room'):typology==='flat-deep-plan-plate'?e.id.includes('-courtyard-'):e.id.includes('primary-space-arrival')||e.id.includes('void-overlook'));
 const result={typology,mode,diagnostic:base.domainDiagnostic,target:target.provenance,targetCenter:center(target),targetIds:rawLetterTarget?memberIds:targetIds,rawTopology:base.typologyDebug.rawTopology,tests:Object.fromEntries(Object.entries(cases).map(([test,r])=>[test,{components:r.presentationMesh.componentCount,extent:r.domainDiagnostic?.final,unsupported:r.elements.length===0,failures:r.validation.failures,targetGeometryChanged:hash(identify(r).map(geometric))!==hash(identify(base).map(geometric)),targets:identify(r).map(e=>({id:e.id,center:center(e),provenance:e.provenance})),allElementsAssigned:r.elements.every(e=>!!e.provenance)}]))};rows.push(result);
 const name=typology+'-'+mode;
 fs.writeFileSync(path.join(__dirname,name+'-assignments.json'),JSON.stringify({source:fixture.source,regions:[...analysis.letters,...analysis.voids],relationships:analysis.relationships,elements:base.elements,raw:base.disconnectedElements,tests:result.tests},null,2));
 for(const [test,r] of Object.entries(cases))fs.writeFileSync(path.join(__dirname,name+'-'+test+'.svg'),svg(r.presentationMesh,`${mode} / ${test}`));
 fs.writeFileSync(path.join(__dirname,name+'-map.svg'),mapSvg(base,target,'Gold: assigned source → target geometry'));
